import { TypedParam, TypedRoute } from "@nestia/core";
import { Controller } from "@nestjs/common";
import typia, { tags } from "typia";

import { ITodoAppTodo } from "../../../../api/structures/ITodoAppTodo";
import { UserAuth } from "../../../../decorators/UserAuth";
import { UserPayload } from "../../../../decorators/payload/UserPayload";
import { deleteTodoAppUserTrashesId } from "../../../../providers/deleteTodoAppUserTrashesId";
import { postTodoAppUserTrashesIdRestore } from "../../../../providers/postTodoAppUserTrashesIdRestore";

@Controller("/todoApp/user/trashes/:id")
export class TodoappUserTrashesController {
  /**
   * Restore a todo item from the trash back to the active list.
   *
   * This operation moves a previously soft-deleted todo from the trash view back to the primary todo list, making it visible in regular todo views. The restored todo retains all its edit history, original completion status, dates, and associated details.
   *
   * The authenticated user must be the owner of the todo being restored (verified via user ID checks against the database). The completion status of the restored todo is reset to INCOMPLETE, matching the state it was in before being moved to trash.
   *
   * All associated edit history entries (todo_app_histories) are preserved without modification, ensuring full audit trail visibility. This operation does not require any input data - only the target todo ID in the path parameter.
   *
   * @param connection
   * @param id ID of the todo to restore, must match the user's deleted todo
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor user
   * @x-autobe-specification Service layer verifies user ownership of the todo by checking against authenticated user ID. Sets 'deleted_at' to null and resets completion status to INCOMPLETE. Preserves all historical edits (via todo_app_histories) without modification. Returns the fully restored todo entity with updated active state. Performs this as a single transaction to maintain data integrity.
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Post("restore")
  public async restore(
    @UserAuth()
    user: UserPayload,
    @TypedParam("id")
    id: string & tags.Format<"uuid">,
  ): Promise<ITodoAppTodo> {
    try {
      return await postTodoAppUserTrashesIdRestore({
        user,
        id,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }

  /**
   * Permanently delete a todo item from the trash.
   *
   * This endpoint allows users to purge a todo item that was previously marked as deleted (soft-deleted) from the system. When called, the todo and all associated edit history entries are permanently removed from the database with no possibility of restoration.
   *
   * The operation requires that the todo must be currently in the trash state (soft-deleted) to be eligible for permanent deletion. Users can access this endpoint to clean up their trash and free up database storage.
   *
   * Note: This action cannot be undone. It is designed for permanent cleanup of unnecessary trash items that have not been restored.
   *
   * @param connection
   * @param id Unique identifier of the todo item to permanently delete
   * @x-autobe-authorization-type null
   * @x-autobe-authorization-actor user
   * @x-autobe-specification 1. Verify user owns the todo in trash (via todo_app_todos.deleted_at IS NOT NULL)
   * 2. Identify associated history entries (todo_app_histories.todo_id = id)
   * 3. Delete all related history entries (todo_app_histories)
   * 4. Permanently delete the todo record (todo_app_todos)
   * 5. Return 204 No Content
   * 6. Handle edge case: 404 if todo not found in trash
   * @nestia Generated by Nestia - https://github.com/samchon/nestia
   */
  @TypedRoute.Delete()
  public async erase(
    @UserAuth()
    user: UserPayload,
    @TypedParam("id")
    id: string & tags.Format<"uuid">,
  ): Promise<void> {
    try {
      return await deleteTodoAppUserTrashesId({
        user,
        id,
      });
    } catch (error) {
      console.log(error);
      throw error;
    }
  }
}
